const response = $json.choices?.[0]?.message?.content || '{}';
const parsed = JSON.parse(response);
return {
  ...$('Auth + Normalize').first().json,
  vision_producto: parsed.producto || 'no_identificado',
  vision_confianza: parsed.confianza || 0,
  vision_payment_proof: parsed.payment_proof || false,
  vision_razon: parsed.razon || '',
  message_text: `[Imagen recibida: ${parsed.producto} (confianza ${parsed.confianza})]`
};

const currentStage = $('Auth + Normalize').first().json.stage;
const mediaUrl = $('Auth + Normalize').first().json.media_url;

const STAGE_IDS = {
  'Esperando Pago': '843a06f1-1214-4baa-a3a0-f197cb240b5d',
  'Pago Confirmado': '96d760e5-f290-456c-a117-57e61ce6c27d'
};

let nextStageId = null;
let mensaje = '';
let notifyOscar = false;
let comprobanteField = null;

if (currentStage === 'Cotizado') {
  nextStageId = STAGE_IDS['Esperando Pago'];
  mensaje = '¡Recibí tu comprobante! 🎉 Lo verificamos en breve y te confirmamos.';
  comprobanteField = 'anticipo';
} else if (currentStage === 'Esperando Pago') {
  nextStageId = STAGE_IDS['Pago Confirmado'];
  mensaje = '¡Pago confirmado! ✅ Ahora pasamos al diseño de tus recuerditos 🎨';
  notifyOscar = true;
  comprobanteField = 'liquidacion';
} else {
  mensaje = 'Comprobante recibido, un asesor te contactará pronto.';
}

return {
  ...$('Auth + Normalize').first().json,
  nextStageId,
  mensaje,
  notifyOscar,
  currentStage,
  comprobanteField,
  mediaUrl
};

const row = $json;
const messages = Array.isArray(row.pending_messages) ? row.pending_messages : JSON.parse(row.pending_messages || '[]');
const combinedText = messages.join('\n');

return {
  ...$('Auth + Normalize').first().json,
  message_text: combinedText
};

let text = $json.output || '';

text = text.trim();
if ((text.startsWith('"') && text.endsWith('"')) || (text.startsWith("'") && text.endsWith("'"))) {
  text = text.slice(1, -1);
}

// markdown -> WhatsApp
text = text.replace(/\*\*/g, '*');
text = text.replace(/^#{1,6}\s*/gm, '');

// Linea que pertenece a un bloque FIJO del negocio (cotizacion / 7 pasos / promo):
// no se humaniza ni se parte, va entera.
const isCanon = (l) =>
  /⏳|HAZ TU PEDIDO|SENCILLOS PASOS|SEMANA LOCA|DIAS DE PROMO|MUESTRA DIGITAL|PAGO FINAL|FOTO DEL PRODUCTO|COTIZACION de los|ANTICIPO para desarrollar/i.test(l) ||
  /^\s*\d+[.)]\s/.test(l) ||                                                  // pasos numerados
  /x\s*\$|^\s*(Total|Env[íi]o|Anticipo|Subtotal)\s*[:(]/i.test(l);            // lineas de cotizacion

// nunca revelar peso
text = text.split('\n').filter(l => !/\bkg\b|\bpeso\b|\bkilogramos?\b/i.test(l)).join('\n');

// humanizacion: sin signos de apertura (salvo bloques fijos)
text = text.split('\n').map(l => isCanon(l) ? l : l.replace(/[¿¡]/g, '')).join('\n');

// ningun telefono que no sea el oficial
const OFICIAL = '3315948670';
text = text.replace(/\b\d{7,10}\b/g, (m) => (m === OFICIAL ? m : ''));
text = text.replace(/[ \t]{2,}/g, ' ');

// ---- agrupado en mensajes de WhatsApp ----
// cada linea conversacional = su propia burbuja; los bloques fijos se mandan enteros.
const parts = [];
let buf = [], bufCanon = false;
const flush = () => { const s = buf.join('\n').trim(); if (s) parts.push(s); buf = []; };

for (const raw of text.split('\n')) {
  const line = raw.trim();
  if (!line) { flush(); bufCanon = false; continue; }
  if (isCanon(line)) {
    if (!bufCanon) flush();
    buf.push(line);
    bufCanon = true;
  } else {
    if (bufCanon) { flush(); bufCanon = false; }
    parts.push(line);
  }
}
flush();

// tope de burbujas: el excedente se junta en la ultima
const MAX = 6;
let out = parts.filter(Boolean);
if (out.length > MAX) out = out.slice(0, MAX - 1).concat([out.slice(MAX - 1).join('\n')]);
if (!out.length) out = [text.trim()];

return out.map((p) => ({ message_part: p }));

const customFields = $json.opportunity?.customFields || [];
const EVENTO_FIELD_ID = 'ahVpF5ldsRcuOIn9Mxdk';
const eventoField = customFields.find(cf => cf.id === EVENTO_FIELD_ID);
const currentEvento = eventoField ? (Array.isArray(eventoField.fieldValue) ? eventoField.fieldValue[0] : eventoField.fieldValue) : '';

const incomingEvento = $('Auth + Normalize').first().json.custom_fields.evento_detectado || '';
const justSet = (!incomingEvento || incomingEvento === '') && currentEvento && currentEvento !== '';

const IMAGENES = {
  'Boda': 'https://assets.cdn.filesafe.space/onRwi0ZF4uYi0Lp6GAbE/media/94d1527d-83d1-40e2-bfac-05dd969c3ea7.jpg',
  'XV': 'https://assets.cdn.filesafe.space/onRwi0ZF4uYi0Lp6GAbE/media/136d7ce1-0487-4767-a408-16742a068939.jpg'
};
const imagenUrl = IMAGENES[currentEvento] || 'https://assets.cdn.filesafe.space/onRwi0ZF4uYi0Lp6GAbE/media/10880c83-56c2-4ee3-b30d-71e910093962.jpg';

const productosBase = 'TENEMOS ESTOS PRODUCTOS PARA TU EVENTO:\n\n*Sandalias*\n*Cilindros*\n';
const mandilLine = currentEvento === 'Boda' ? '*Mandiles para Boda*\n' : '';
const descripcion = `${productosBase}${mandilLine}*Kit anti cruda*\n*Pantuflas*\n\nCuales te interesan?`;

const promoText = 'Que padre! \ud83d\ude0a\n\n\ud83c\udf89 *\u00a1SEMANA LOCA DE PROMOS! SOLO 7 D\u00cdAS PARA LLEVARTE TUS RECUERDITOS PERSONALIZADOS CON DESCUENTAZO* \ud83c\udf89\n\n*(Pedidos solo para eventos 2026 por tema de tiempos)*';

return {
  ...$('Auth + Normalize').first().json,
  currentEvento,
  justSet,
  imagenUrl,
  descripcion,
  promoText
};

const PAUSED_STAGES = ['Esperando Pago', 'Pago Confirmado', 'Diseño en Proceso', 'En Producción', 'Enviado'];
const stage = $('Auth + Normalize').first().json.stage;
const isPausedStage = PAUSED_STAGES.includes(stage);

return {
  ...$json,
  isPausedStage
};

